```typescript
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

// The function under test
interface RetryOptions {
  maxRetries?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
  jitter?: boolean;
}

async function retryWithBackoff<T>(
  fn: () => Promise<T>,
  options: RetryOptions = {}
): Promise<T> {
  const {
    maxRetries = 3,
    baseDelayMs = 1000,
    maxDelayMs = 30000,
    jitter = false,
  } = options;

  let lastError: Error | undefined;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      if (attempt === maxRetries) {
        break;
      }

      let delay = Math.min(baseDelayMs * 2 ** attempt, maxDelayMs);
      if (jitter) {
        delay = delay * (0.5 + Math.random() * 0.5);
      }

      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }

  throw lastError;
}

// Tests
describe('retryWithBackoff', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('returns immediately on first success', async () => {
    const fn = vi.fn().mockResolvedValue('ok');

    const promise = retryWithBackoff(fn);
    const result = await promise;

    expect(result).toBe('ok');
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it('retries on failure and returns on eventual success', async () => {
    const fn = vi
      .fn()
      .mockRejectedValueOnce(new Error('fail 1'))
      .mockRejectedValueOnce(new Error('fail 2'))
      .mockResolvedValue('success');

    const promise = retryWithBackoff(fn, { maxRetries: 3, baseDelayMs: 100 });

    // First retry delay: 100ms
    await vi.advanceTimersByTimeAsync(100);
    // Second retry delay: 200ms
    await vi.advanceTimersByTimeAsync(200);

    const result = await promise;

    expect(result).toBe('success');
    expect(fn).toHaveBeenCalledTimes(3);
  });

  it('throws after exhausting all retries', async () => {
    const fn = vi.fn().mockRejectedValue(new Error('persistent failure'));

    const promise = retryWithBackoff(fn, { maxRetries: 2, baseDelayMs: 100 });

    await vi.advanceTimersByTimeAsync(100); // attempt 1 -> retry
    await vi.advanceTimersByTimeAsync(200); // attempt 2 -> retry

    await expect(promise).rejects.toThrow('persistent failure');
    expect(fn).toHaveBeenCalledTimes(3); // initial + 2 retries
  });

  it('applies exponential backoff delays', async () => {
    const fn = vi.fn().mockRejectedValue(new Error('fail'));
    const setTimeoutSpy = vi.spyOn(global, 'setTimeout');

    const promise = retryWithBackoff(fn, {
      maxRetries: 4,
      baseDelayMs: 1000,
    });

    // Advance through all retries
    await vi.advanceTimersByTimeAsync(1000);  // 1000 * 2^0
    await vi.advanceTimersByTimeAsync(2000);  // 1000 * 2^1
    await vi.advanceTimersByTimeAsync(4000);  // 1000 * 2^2
    await vi.advanceTimersByTimeAsync(8000);  // 1000 * 2^3

    await expect(promise).rejects.toThrow('fail');

    // Verify delays were called with exponential values
    const timeoutCalls = setTimeoutSpy.mock.calls
      .map(([, ms]) => ms)
      .filter((ms): ms is number => typeof ms === 'number' && ms > 0);

    expect(timeoutCalls).toEqual([1000, 2000, 4000, 8000]);
  });

  it('caps delay at maxDelayMs', async () => {
    const fn = vi.fn().mockRejectedValue(new Error('fail'));
    const setTimeoutSpy = vi.spyOn(global, 'setTimeout');

    const promise = retryWithBackoff(fn, {
      maxRetries: 4,
      baseDelayMs: 1000,
      maxDelayMs: 3000,
    });

    await vi.advanceTimersByTimeAsync(1000);
    await vi.advanceTimersByTimeAsync(2000);
    await vi.advanceTimersByTimeAsync(3000); // capped
    await vi.advanceTimersByTimeAsync(3000); // capped

    await expect(promise).rejects.toThrow('fail');

    const timeoutCalls = setTimeoutSpy.mock.calls
      .map(([, ms]) => ms)
      .filter((ms): ms is number => typeof ms === 'number' && ms > 0);

    expect(timeoutCalls).toEqual([1000, 2000, 3000, 3000]);
  });

  it('applies jitter when enabled', async () => {
    vi.spyOn(Math, 'random').mockReturnValue(0.5); // deterministic

    const fn = vi.fn().mockRejectedValue(new Error('fail'));
    const setTimeoutSpy = vi.spyOn(global, 'setTimeout');

    const promise = retryWithBackoff(fn, {
      maxRetries: 2,
      baseDelayMs: 1000,
      jitter: true,
    });

    // With random=0.5, jitter multiplier = 0.5 + 0.5*0.5 = 0.75
    // First delay: 1000 * 0.75 = 750
    await vi.advanceTimersByTimeAsync(750);
    // Second delay: 2000 * 0.75 = 1500
    await vi.advanceTimersByTimeAsync(1500);

    await expect(promise).rejects.toThrow('fail');

    const timeoutCalls = setTimeoutSpy.mock.calls
      .map(([, ms]) => ms)
      .filter((ms): ms is number => typeof ms === 'number' && ms > 0);

    expect(timeoutCalls).toEqual([750, 1500]);
  });

  it('uses default options when none provided', async () => {
    const fn = vi.fn().mockRejectedValue(new Error('fail'));

    const promise = retryWithBackoff(fn);

    await vi.advanceTimersByTimeAsync(1000);  // 2^0 * 1000
    await vi.advanceTimersByTimeAsync(2000);  // 2^1 * 1000
    await vi.advanceTimersByTimeAsync(4000);  // 2^2 * 1000

    await expect(promise).rejects.toThrow('fail');
    expect(fn).toHaveBeenCalledTimes(4); // 1 initial + 3 retries
  });

  it('handles non-Error rejections', async () => {
    const fn = vi.fn().mockRejectedValue('string error');

    const promise = retryWithBackoff(fn, { maxRetries: 0 });

    await expect(promise).rejects.toThrow('string error');
  });

  it('does not retry when maxRetries is 0', async () => {
    const fn = vi.fn().mockRejectedValue(new Error('no retry'));

    const promise = retryWithBackoff(fn, { maxRetries: 0 });

    await expect(promise).rejects.toThrow('no retry');
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it('preserves the resolved value type', async () => {
    const fn = vi.fn().mockResolvedValue({ id: 1, name: 'test' });

    const result = await retryWithBackoff(fn);

    expect(result).toEqual({ id: 1, name: 'test' });
  });

  it('throws the last error, not the first', async () => {
    const fn = vi
      .fn()
      .mockRejectedValueOnce(new Error('error 1'))
      .mockRejectedValueOnce(new Error('error 2'))
      .mockRejectedValueOnce(new Error('error 3'));

    const promise = retryWithBackoff(fn, { maxRetries: 2, baseDelayMs: 100 });

    await vi.advanceTimersByTimeAsync(100);
    await vi.advanceTimersByTimeAsync(200);

    await expect(promise).rejects.toThrow('error 3');
  });
});
```

The tests cover:

- Happy path (immediate success)
- Retry then succeed
- Exhausted retries throwing the last error
- Exponential delay progression (1s, 2s, 4s, 8s...)
- `maxDelayMs` cap enforcement
- Jitter with deterministic `Math.random` mock
- Default options behavior
- Non-Error rejection handling
- Zero retries edge case
- Return type preservation
- Last-error-wins semantics

I included the implementation inline so the tests are self-contained and runnable. In a real project you'd import `retryWithBackoff` from its module. The key testing technique here is `vi.useFakeTimers()` + `vi.advanceTimersByTimeAsync()` to avoid actual waiting while still verifying timing behavior.

# Strategy Pattern in Go

The Strategy pattern defines a family of algorithms, encapsulates each one, and makes them interchangeable. The client code works with any algorithm through a common interface without knowing the implementation details.

Go makes this clean because interfaces are implicit — no "implements" keyword needed.

## Practical Example: Payment Processing

```go
package main

import "fmt"

// Strategy interface
type PaymentStrategy interface {
	Pay(amount float64) error
	Name() string
}

// Concrete strategy: Credit Card
type CreditCard struct {
	Number string
	CVV    string
}

func (c *CreditCard) Pay(amount float64) error {
	fmt.Printf("Paid %.2f via Credit Card ending in %s\n", amount, c.Number[len(c.Number)-4:])
	return nil
}

func (c *CreditCard) Name() string { return "Credit Card" }

// Concrete strategy: PayPal
type PayPal struct {
	Email string
}

func (p *PayPal) Pay(amount float64) error {
	fmt.Printf("Paid %.2f via PayPal (%s)\n", amount, p.Email)
	return nil
}

func (p *PayPal) Name() string { return "PayPal" }

// Concrete strategy: Crypto
type Crypto struct {
	WalletAddress string
}

func (c *Crypto) Pay(amount float64) error {
	fmt.Printf("Paid %.2f via Crypto wallet %s...%s\n", amount, c.WalletAddress[:6], c.WalletAddress[len(c.WalletAddress)-4:])
	return nil
}

func (c *Crypto) Name() string { return "Crypto" }

// Context: the thing that uses a strategy
type Checkout struct {
	strategy PaymentStrategy
}

func (ch *Checkout) SetPaymentMethod(s PaymentStrategy) {
	ch.strategy = s
}

func (ch *Checkout) ProcessOrder(amount float64) error {
	if ch.strategy == nil {
		return fmt.Errorf("no payment method selected")
	}
	fmt.Printf("Processing order with %s...\n", ch.strategy.Name())
	return ch.strategy.Pay(amount)
}

func main() {
	checkout := &Checkout{}

	// Swap strategies at runtime
	checkout.SetPaymentMethod(&CreditCard{Number: "4111111111111234", CVV: "123"})
	checkout.ProcessOrder(99.99)

	fmt.Println()

	checkout.SetPaymentMethod(&PayPal{Email: "user@example.com"})
	checkout.ProcessOrder(49.50)

	fmt.Println()

	checkout.SetPaymentMethod(&Crypto{WalletAddress: "0xABCDEF1234567890"})
	checkout.ProcessOrder(200.00)
}
```

## Output

```
Processing order with Credit Card...
Paid 99.99 via Credit Card ending in 1234

Processing order with PayPal...
Paid 49.50 via PayPal (user@example.com)

Processing order with Crypto...
Paid 200.00 via Crypto wallet 0xABCD...7890
```

## Why this works well in Go

1. **Interfaces are small and implicit.** Any type with `Pay(float64) error` and `Name() string` is a valid strategy. No registration, no base classes.

2. **Easy to extend.** Adding a new payment method means adding a new struct — zero changes to `Checkout`.

3. **Testable.** You can inject a mock strategy in tests without any framework.

4. **Alternative: function type.** For simple cases where the strategy is a single method, you can skip the interface entirely:

```go
type PayFunc func(amount float64) error

func ProcessOrder(amount float64, pay PayFunc) error {
    return pay(amount)
}
```

Use the interface version when strategies carry state or have multiple methods. Use the function version when it's just one behavior with no state. That's idiomatic Go — pick the simplest tool that fits.

```rust
use std::time::Duration;
use std::thread;

/// Retry a fallible operation with exponential backoff.
///
/// - `max_retries`: maximum number of attempts (0 means try once, no retries)
/// - `initial_delay`: base delay before first retry
/// - `max_delay`: cap on the backoff duration
/// - `op`: the operation to retry; receives the current attempt number (0-indexed)
///
/// Returns `Ok(T)` on first success, or the last `Err(E)` after all attempts are exhausted.
pub fn retry_with_backoff<T, E, F>(
    max_retries: u32,
    initial_delay: Duration,
    max_delay: Duration,
    mut op: F,
) -> Result<T, E>
where
    F: FnMut(u32) -> Result<T, E>,
{
    let total_attempts = max_retries.saturating_add(1); // avoid overflow if max_retries == u32::MAX
    let mut last_err: Option<E> = None;

    for attempt in 0..total_attempts {
        match op(attempt) {
            Ok(val) => return Ok(val),
            Err(e) => {
                last_err = Some(e);

                // Don't sleep after the final attempt
                if attempt < max_retries {
                    let exp = attempt.min(63); // prevent shift overflow
                    let backoff = initial_delay.saturating_mul(2u32.saturating_pow(exp));
                    let capped = backoff.min(max_delay);
                    thread::sleep(capped);
                }
            }
        }
    }

    // total_attempts >= 1, so last_err is always Some
    Err(last_err.unwrap())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::Cell;
    use std::time::Instant;

    #[test]
    fn succeeds_immediately() {
        let result = retry_with_backoff(3, Duration::from_millis(10), Duration::from_secs(1), |_| {
            Ok::<_, &str>(42)
        });
        assert_eq!(result, Ok(42));
    }

    #[test]
    fn fails_then_succeeds() {
        let count = Cell::new(0);
        let result = retry_with_backoff(5, Duration::from_millis(1), Duration::from_secs(1), |_| {
            let c = count.get();
            count.set(c + 1);
            if c < 3 {
                Err("not yet")
            } else {
                Ok("done")
            }
        });
        assert_eq!(result, Ok("done"));
        assert_eq!(count.get(), 4);
    }

    #[test]
    fn exhausts_all_retries() {
        let count = Cell::new(0u32);
        let result = retry_with_backoff(2, Duration::from_millis(1), Duration::from_millis(10), |_| {
            count.set(count.get() + 1);
            Err::<(), _>("always fails")
        });
        assert_eq!(result, Err("always fails"));
        assert_eq!(count.get(), 3); // 1 initial + 2 retries
    }

    #[test]
    fn zero_retries_means_single_attempt() {
        let count = Cell::new(0u32);
        let result = retry_with_backoff(0, Duration::from_millis(100), Duration::from_secs(1), |_| {
            count.set(count.get() + 1);
            Err::<(), _>("fail")
        });
        assert_eq!(result, Err("fail"));
        assert_eq!(count.get(), 1);
    }

    #[test]
    fn respects_max_delay_cap() {
        let start = Instant::now();
        let _ = retry_with_backoff(3, Duration::from_millis(500), Duration::from_millis(50), |_| {
            Err::<(), _>("fail")
        });
        let elapsed = start.elapsed();
        // 3 sleeps capped at 50ms each = ~150ms, not 500+1000+2000ms
        assert!(elapsed < Duration::from_millis(300));
    }
}
```

Edge cases handled:

- `max_retries = 0` — runs the operation exactly once, no sleep.
- `max_retries = u32::MAX` — `saturating_add` prevents overflow when computing total attempts.
- Large exponents — `attempt.min(63)` prevents bit-shift overflow in `2^attempt`.
- Huge `initial_delay` — `saturating_mul` prevents `Duration` overflow; `min(max_delay)` caps it.
- No sleep after the final failed attempt — avoids a pointless wait before returning the error.
- `last_err.unwrap()` is safe because the loop always executes at least once.

For production use you'd likely want to add jitter (randomized offset to prevent thundering herd), an async variant using `tokio::time::sleep`, and possibly a predicate to decide which errors are retryable. But this is the correct mechanical core.
